package stonytark.cinemarr.registry;
import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.state.BlockBehaviour;import net.minecraft.world.level.material.MapColor;import net.minecraftforge.registries.*;import stonytark.cinemarr.Cinemarr;import stonytark.cinemarr.screen.*;
public final class CinemarrBlocks{public static final DeferredRegister<Block> REGISTER=DeferredRegister.create(ForgeRegistries.BLOCKS,Cinemarr.MODID);private static BlockBehaviour.Properties electronic(){return BlockBehaviour.Properties.of().mapColor(MapColor.COLOR_BLACK).strength(2,6).sound(SoundType.METAL);}public static final RegistryObject<ScreenPixelBlock> SCREEN_PIXEL=REGISTER.register("screen_pixel",()->new ScreenPixelBlock(electronic().noOcclusion()));public static final RegistryObject<TvControllerBlock> TV_CONTROLLER=REGISTER.register("tv_controller",()->new TvControllerBlock(electronic()));public static final RegistryObject<Block> TV_CASING=REGISTER.register("tv_casing",()->new Block(electronic()));public static final RegistryObject<Block> TV_SPEAKER=REGISTER.register("tv_speaker",()->new Block(electronic()));private CinemarrBlocks(){}}
